  static FoodItem _food({
    required String name,
    required String nameUrdu,
    required double cal,
    required double protein,
    required double carbs,
    required double fat,
    required double fiber,
    required FoodCategory category,
    String? family,
    String type = 'variant',
    List<String> ingredients = const [],
    bool supportsCookingMethod = false,
    String? seedId,
    List<String> searchTokens = const [],
    List<String> phoneticTokens = const [],
    int staticRank = 0,
    int schemaVersion = 1,
    double sugar = 0.0,
    double satietyScore = 5.0,
    double waterPercentage = 0.0,
    bool isLiquid = false,
    bool isUltraProcessed = false,
    double? piece,
    double? plate,
    double? bowl,
    double? cup,
  }) {
    return FoodItem()
      ..name = name
      ..nameUrdu = nameUrdu
      ..family = family
      ..type = type
      ..ingredients = ingredients
      ..supportsCookingMethod = supportsCookingMethod
      ..seedId = seedId
      ..searchTokens = searchTokens
      ..phoneticTokens = phoneticTokens
      ..staticRank = staticRank
      ..schemaVersion = schemaVersion
      ..caloriesPer100g = cal
      ..proteinPer100g = protein
      ..carbsPer100g = carbs
      ..fatPer100g = fat
      ..fiberPer100g = fiber
      ..sugarPer100g = sugar
      ..satietyScore = satietyScore
      ..waterPercentage = waterPercentage
      ..isLiquid = isLiquid
      ..isUltraProcessed = isUltraProcessed
      ..category = category
      ..servingPiece = piece
      ..servingPlate = plate
      ..servingBowl = bowl
      ..servingCup = cup
      ..isPakistani = true;
  }
